# Build stored cases CO-226..CO-228 from the probe households (generated by mk.py into a scratch copy).
import sys, yaml, copy
src, out = sys.argv[1], sys.argv[2]
cases = {c['id']: c for c in yaml.safe_load(open(src)) if c['id'].startswith('RV3-')}

def body(c, newid, title, comment, expect, tweak=None):
    c = copy.deepcopy(c)
    if tweak: tweak(c)
    d = {'id': newid, 'title': title, 'as_of': c['as_of'], 'persons': c['persons']}
    if c.get('relationships'): d['relationships'] = c['relationships']
    txt = yaml.safe_dump([d], sort_keys=False, allow_unicode=True, width=1000)
    lines = txt.rstrip('\n').split('\n')
    # comments after the title line
    lines = lines[:2] + ['  # ' + l for l in comment] + lines[2:]
    lines.append('  expect:')
    for pid, ex in expect.items():
        lines.append('    %s:' % pid)
        for k, v in ex:
            lines.append('      %s: %s' % (k, v))
    return '\n'.join(lines) + '\n'

def fph(c):
    c['persons']['p1']['month_defaults']['electronic_data_source_monthly_gross_income'] = 1995

t = []
